yaml:
layout:
  TwoHorizontalGraphs:
    leftGraph:
      xAxis: {title: Left X Axis}
      yAxis: {title: Left Y Axis}
    rightGraph:
      xAxis: {title: Right X Axis}
      yAxis: {title: Right Y Axis}

params:
  - {name: ax, value: 8, round: 0.01}
  - {name: ay, value: 5, round: 0.01}
  - {name: bx, value: 2, round: 0.01}
  - {name: by, value: 5, round: 0.01}
  - {name: cx, value: 8, round: 0.01}
  - {name: cy, value: 8, round: 0.01}
layout:
  OneGraph:
    graph:
      objects:
      - Angle:
          pointA:
            coordinates: [params.ax, params.ay]
            draggable: true
            label: {text: A, position: tl}
          pointB:
            coordinates: [params.bx, params.by]
            draggable: true
            label: {text: B, position: l}
          pointC:
            coordinates: [params.cx, params.cy]
            draggable: true
            label: {text: C}
          showSegments: true

layout:
  OneGraph:
    graph:
      xAxis: {ticks: 0}
      yAxis: {ticks: 0}
      objects:

      - Point:
          coordinates: [6,4]
          label:
            text: \text{A blue point}
          droplines:
            vertical: x\text{ value}
            horizontal: y\text{ value}

      - Point:
          coordinates: [3,3]
          color: red
          label:
            text: \text{A red point}
            position: tr

layout:
  OneGraph:
    graph:
      objects:
      - Circle: {c: [4,4], r: 2, fill: none}
      - Circle: {c: [6,4], r: 2, fill: none}
      - Overlap:
          fill: purple
          shapes:
          - Circle: {c: [4,4], r: 2}
          - Circle: {c: [6,4], r: 2}

layout:
  OneGraph:
    graph:
      objects:
      - Circle: {c: [4,4], r: 2, fill: none}
      - Circle: {c: [6,4], r: 2, fill: none}
      - Rectangle:
          a: [0,0]
          b: [10,10]
          fill: purple
          clipPaths:
          - Circle: {c: [4,4], r: 2}
          - Circle: {c: [6,4], r: 2}

layout:
  OneGraph:
    graph:
      objects:
      - Circle: {c: [4,4], r: 2, fill: purple}
      - Circle: {c: [6,4], r: 2, fill: purple}

layout:
  OneGraph:
    graph:
      objects:

      # default
      - Line: {yIntercept: 10}

      # thin
      - Line: {strokeWidth: 0.5, yIntercept: 8}

      # thick
      - Line: {strokeWidth: 10, yIntercept: 6}

      # dashed
      - Line: {lineStyle: dashed, yIntercept: 4}

      # dotted
      - Line: {lineStyle: dotted, yIntercept: 2}

params:
- {name: a, value: 3, min: 0, max: 10}
- {name: b, value: 0.5, min: 0, max: 1, round: 0.1}
layout:
  HTMLPlusSidebarLayout:
    html: "`<p>The value of $a$ is ${params.a}.</p><p>The value of $b$ is ${params.b.toFixed(1)}.</p><p>Let's add $a$ and $b$ together: $$ ${params.a} + ${params.b.toFixed(1)} = ${(params.a + params.b).toFixed(1)}$$</p>`"
    sidebar:
      controls:
      - title: Adding Parameters
        sliders:
        - {param: a, label: a}
        - {param: b, label: b}

params:
- {name: a, value: 3}
- {name: b, value: 0.5}
layout:
  HTMLLayout:
    html: "`<p>The value of $a$ is ${params.a}.</p><p>The value of $b$ is ${params.b}.</p>`"
